CREATE INDEX moderation_cases_status_priority_idx ON public.moderation_cases(status,severity,created_at DESC); CREATE INDEX moderation_case_links_case_idx ON public.moderation_case_links(case_id); CREATE INDEX moderation_case_events_case_idx ON public.moderation_case_events(case_id,created_at); CREATE INDEX risk_signals_subject_idx ON public.risk_signals(subject_type,subject_id,created_at DESC); CREATE INDEX risk_score_history_subject_idx ON public.risk_score_history(subject_type,subject_id,calculated_at DESC); CREATE INDEX verification_history_entity_idx ON public.verification_history(entity_type,entity_id,created_at DESC); CREATE INDEX review_moderation_status_idx ON public.review_moderation(moderation_status);

