 ('student-documents','student-documents',false,10485760,ARRAY['image/jpeg','image/png','image/webp','application/pdf']),
 ('vendor-documents','vendor-documents',false,10485760,ARRAY['image/jpeg','image/png','image/webp','application/pdf']),
 ('university-branding','university-branding',true,5242880,ARRAY['image/jpeg','image/png','image/webp']) ON CONFLICT(id) DO NOTHING;
CREATE POLICY avatar_upload_own_folder ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY student_document_owner ON storage.objects FOR ALL TO authenticated USING(bucket_id='student-documents' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='student-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY vendor_document_owner ON storage.objects FOR ALL TO authenticated USING(bucket_id='vendor-documents' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='vendor-documents' AND (storage.foldername(name))[1]=auth.uid()::text);
